        _e("kv2_dsa_monotonic","Monotonic Stack","algorithms","# Next Greater Element\ndef next_greater(nums):\n    n = len(nums)\n    result = [-1] * n\n    stack = []  # indices\n    for i in range(n):\n        while stack and nums[i] > nums[stack[-1]]:\n            result[stack.pop()] = nums[i]\n        stack.append(i)\n    return result\n\n# Daily Temperatures\ndef daily_temperatures(T):\n    n = len(T)\n    result = [0] * n\n    stack = []\n    for i in range(n):\n        while stack and T[i] > T[stack[-1]]:\n            j = stack.pop()\n            result[j] = i - j\n        stack.append(i)\n    return result\n\n# Applications: next greater/smaller, stock span, largest rectangle in histogram, trapping rain water",["algorithms","monotonic-stack","stack","next-greater","pattern"]),
        _e("kv2_dsa_topological","Topological Sort","algorithms","from collections import defaultdict, deque\n\ndef topological_sort(n, edges):\n    graph = defaultdict(list)\n    indegree = [0] * n\n    for u, v in edges:\n        graph[u].append(v)\n        indegree[v] += 1\n    \n    queue = deque(i for i in range(n) if indegree[i] == 0)\n    order = []\n    while queue:\n        node = queue.popleft()\n        order.append(node)\n        for nei in graph[node]:\n            indegree[nei] -= 1\n            if indegree[nei] == 0:\n                queue.append(nei)\n    \n    return order if len(order) == n else []  # empty = cycle\n\n# Applications: build systems, course prerequisites, task scheduling, dependency resolution\n# DFS version: reverse postorder",["algorithms","topological-sort","graph","dag","kahn","bfs"]),
